pub fn dispatch_entity_keyword_deprecate(
    repo: &mut impl crate::kernel::Repository<Syntax>,
    parent_id: &str,
    element_id: &str,
    element_wants: &str,
    args: KeywordDeprecateEntityArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Syntax> {
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, SYNTAX_PROJECTED_FIELDS);

    crate::kernel::dispatch_entity(
        repo,
        parent_id,
        |r: &Syntax| &r.keywords,
        |r: &mut Syntax| &mut r.keywords,
        |el: &Keyword| el.identity() == element_id,
        "Deprecate",
        "Bluebook::Syntax",
        "Syntax",
        "name.value",
        "Keyword",
        "position.value",
        element_wants,
        &with_references,
        &[],
        Some(crate::kernel::TransitionCheck {
            field: "status",
            from_states: &["admitted"],
        }),
        |record| {
            record.status = "deprecated".to_string();
            Ok(())
        },
        &[],
        &syntax_invariants(),
        &["KeywordDeprecated"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

