#[derive(Debug, Clone)]
pub struct KeywordArgs {
    pub position: KeywordPosition,
    pub word: KeywordSeedText,
    pub context: KeywordSeedText,
    pub body: KeywordSeedText,
    pub inner: KeywordSeedText,
    pub opens: KeywordSeedText,
    pub fills: KeywordSeedText,
    pub was: Option<KeywordSeedText>,
    pub resolves_via: Option<KeywordSeedText>,
    pub disambiguator: Option<KeywordSeedText>,
    pub calls: Option<KeywordSeedText>,
}

pub fn dispatch_keyword(
    repo: &mut impl crate::kernel::Repository<Syntax>,
    id: &str,
    args: KeywordArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Syntax> {
    args.position.check_invariants()?;
    args.word.check_invariants()?;
    if ![
        "File",
        "Bluebook",
        "Aggregate",
        "Entity",
        "Command",
        "Query",
        "ValueObject",
        "OneOf",
        "Lifecycle",
        "Policy",
        "ProcessManager",
        "Handler",
        "Dispatch",
        "ReadModel",
        "Type",
        "Hecksagon",
        "World",
        "DomainPort",
        "PortOperation",
        "Port",
        "Adapter",
        "Translation",
        "TranslationAggregate",
        "ContextMap",
    ]
    .contains(&args.context.value.as_str())
    {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "context",
                admits: "Syntax::Context",
                admitted: &[
                    "File",
                    "Bluebook",
                    "Aggregate",
                    "Entity",
                    "Command",
                    "Query",
                    "ValueObject",
                    "OneOf",
                    "Lifecycle",
                    "Policy",
                    "ProcessManager",
                    "Handler",
                    "Dispatch",
                    "ReadModel",
                    "Type",
                    "Hecksagon",
                    "World",
                    "DomainPort",
                    "PortOperation",
                    "Port",
                    "Adapter",
                    "Translation",
                    "TranslationAggregate",
                    "ContextMap",
                ],
                offered: format!("{:?}", args.context.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.context.check_invariants()?;
    if !["none", "keywords", "source", "rows"].contains(&args.body.value.as_str()) {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "body",
                admits: "Syntax::Body",
                admitted: &["none", "keywords", "source", "rows"],
                offered: format!("{:?}", args.body.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.body.check_invariants()?;
    args.inner.check_invariants()?;
    args.opens.check_invariants()?;
    args.fills.check_invariants()?;
    if let Some(v) = &args.was {
        v.check_invariants()?;
    }
    if let Some(__optional_value) = &args.resolves_via {
        if !["hash_chain", "owner_keyed", "sibling_scan"].contains(&__optional_value.value.as_str())
        {
            return Err(crate::kernel::Refusal::InvariantViolation(
                crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                    name: "resolves_via",
                    admits: "Syntax::ResolutionScope",
                    admitted: &["hash_chain", "owner_keyed", "sibling_scan"],
                    offered: format!("{:?}", __optional_value.value).as_str(),
                }
                .render_args(),
            ));
        }
    }
    if let Some(v) = &args.resolves_via {
        v.check_invariants()?;
    }
    if let Some(__optional_value) = &args.disambiguator {
        if !["declared_by"].contains(&__optional_value.value.as_str()) {
            return Err(crate::kernel::Refusal::InvariantViolation(
                crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                    name: "disambiguator",
                    admits: "Syntax::Disambiguator",
                    admitted: &["declared_by"],
                    offered: format!("{:?}", __optional_value.value).as_str(),
                }
                .render_args(),
            ));
        }
    }
    if let Some(v) = &args.disambiguator {
        v.check_invariants()?;
    }
    if let Some(v) = &args.calls {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, SYNTAX_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Keyword",
        "Bluebook::Syntax",
        "Syntax",
        "name.value",
        &with_references,
        &[],
        None,
        |record| {
            if record
                .keywords
                .iter()
                .any(|e| e.position == args.position.clone())
            {
                let offered = format!("{:?}", args.position.clone().value);
                return Err(crate::kernel::Refusal::AlreadyExists(
                    crate::kernel::refusal_wording::AlreadyExistsEntityDuplicateArgs {
                        entity: "Keyword",
                        aggregate: "Syntax",
                        identity: "position.value",
                        offered: &[offered.as_str()],
                    }
                    .render_args(),
                ));
            }
            record.keywords.push(Keyword {
                position: args.position.clone(),
                word: args.word.clone(),
                context: args.context.clone(),
                body: args.body.clone(),
                inner: args.inner.clone(),
                opens: args.opens.clone(),
                fills: args.fills.clone(),
                was: args.was.clone(),
                resolves_via: args.resolves_via.clone(),
                disambiguator: args.disambiguator.clone(),
                calls: args.calls.clone(),
                status: "admitted".to_string(),
            });
            Ok(())
        },
        &[],
        &syntax_invariants(),
        &["KeywordAdmitted"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

