impl crate::kernel::Fielded for ArgumentArgs {
    fn field(&self, name: &str) -> Option<crate::kernel::Field<'_>> {
        use crate::kernel::Field;
        use crate::kernel::Value;
        match name {
            "position" => Some(Field::Nested(&self.position)),
            "keyword" => Some(Field::Nested(&self.keyword)),
            "context" => Some(Field::Nested(&self.context)),
            "at" => self
                .at
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "named" => self
                .named
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "kind" => Some(Field::Nested(&self.kind)),
            "required" => Some(Field::Nested(&self.required)),
            "fills" => Some(Field::Nested(&self.fills)),
            "selects" => self
                .selects
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "pair_key_fills" => self
                .pair_key_fills
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "pair_value_fills" => self
                .pair_value_fills
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "pairs_shape" => self
                .pairs_shape
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "variadic" => self
                .variadic
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "minimum" => self
                .minimum
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "coerce" => self
                .coerce
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "blank_message" => self
                .blank_message
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            _ => None,
        }
    }

    fn items(&self, name: &str) -> Option<Vec<crate::kernel::Field<'_>>> {
        #[allow(unused_imports)]
        use crate::kernel::{Field, Value};
        match name {
            _ => None,
        }
    }

    fn as_scalar(&self) -> Option<crate::kernel::Value> {
        None
    }
}

#[derive(Debug, Clone)]
pub struct ArgumentArgs {
    pub position: ArgumentPosition,
    pub keyword: ArgumentSeedText,
    pub context: ArgumentSeedText,
    pub at: Option<ArgumentSeedText>,
    pub named: Option<ArgumentSeedText>,
    pub kind: ArgumentSeedText,
    pub required: ArgumentSeedText,
    pub fills: ArgumentSeedText,
    pub selects: Option<ArgumentSeedText>,
    pub pair_key_fills: Option<ArgumentSeedText>,
    pub pair_value_fills: Option<ArgumentSeedText>,
    pub pairs_shape: Option<ArgumentSeedText>,
    pub variadic: Option<ArgumentSeedText>,
    pub minimum: Option<ArgumentSeedText>,
    pub coerce: Option<ArgumentSeedText>,
    pub blank_message: Option<ArgumentSeedText>,
}

pub fn dispatch_argument(
    repo: &mut impl crate::kernel::Repository<Syntax>,
    id: &str,
    args: ArgumentArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Syntax> {
    args.position.check_invariants()?;
    args.keyword.check_invariants()?;
    if ![
        "File",
        "Bluebook",
        "Aggregate",
        "Entity",
        "Command",
        "Query",
        "ValueObject",
        "OneOf",
        "Lifecycle",
        "Policy",
        "ProcessManager",
        "Handler",
        "Dispatch",
        "ReadModel",
        "Type",
        "Hecksagon",
        "World",
        "DomainPort",
        "PortOperation",
        "Port",
        "Adapter",
        "Translation",
        "TranslationAggregate",
        "ContextMap",
    ]
    .contains(&args.context.value.as_str())
    {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "context",
                admits: "Syntax::Context",
                admitted: &[
                    "File",
                    "Bluebook",
                    "Aggregate",
                    "Entity",
                    "Command",
                    "Query",
                    "ValueObject",
                    "OneOf",
                    "Lifecycle",
                    "Policy",
                    "ProcessManager",
                    "Handler",
                    "Dispatch",
                    "ReadModel",
                    "Type",
                    "Hecksagon",
                    "World",
                    "DomainPort",
                    "PortOperation",
                    "Port",
                    "Adapter",
                    "Translation",
                    "TranslationAggregate",
                    "ContextMap",
                ],
                offered: format!("{:?}", args.context.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.context.check_invariants()?;
    if let Some(v) = &args.at {
        v.check_invariants()?;
    }
    if let Some(v) = &args.named {
        v.check_invariants()?;
    }
    if ![
        "text", "symbol", "number", "flag", "literal", "constant", "pairs", "list",
    ]
    .contains(&args.kind.value.as_str())
    {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "kind",
                admits: "Syntax::ArgumentKind",
                admitted: &[
                    "text", "symbol", "number", "flag", "literal", "constant", "pairs", "list",
                ],
                offered: format!("{:?}", args.kind.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.kind.check_invariants()?;
    args.required.check_invariants()?;
    args.fills.check_invariants()?;
    if let Some(v) = &args.selects {
        v.check_invariants()?;
    }
    if let Some(v) = &args.pair_key_fills {
        v.check_invariants()?;
    }
    if let Some(v) = &args.pair_value_fills {
        v.check_invariants()?;
    }
    if let Some(v) = &args.pairs_shape {
        v.check_invariants()?;
    }
    if let Some(v) = &args.variadic {
        v.check_invariants()?;
    }
    if let Some(v) = &args.minimum {
        v.check_invariants()?;
    }
    if let Some(v) = &args.coerce {
        v.check_invariants()?;
    }
    if let Some(v) = &args.blank_message {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, SYNTAX_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Argument",
        "Bluebook::Syntax",
        "Syntax",
        "name.value",
        &with_references,
        &[],
        None,
        |record| {
            if record
                .arguments
                .iter()
                .any(|e| e.position == args.position.clone())
            {
                let offered = format!("{:?}", args.position.clone().value);
                return Err(crate::kernel::Refusal::AlreadyExists(
                    crate::kernel::refusal_wording::AlreadyExistsEntityDuplicateArgs {
                        entity: "Argument",
                        aggregate: "Syntax",
                        identity: "position.value",
                        offered: &[offered.as_str()],
                    }
                    .render_args(),
                ));
            }
            record.arguments.push(Argument {
                position: args.position.clone(),
                keyword: args.keyword.clone(),
                context: args.context.clone(),
                at: args.at.clone(),
                named: args.named.clone(),
                kind: args.kind.clone(),
                required: args.required.clone(),
                fills: args.fills.clone(),
                selects: args.selects.clone(),
                pair_key_fills: args.pair_key_fills.clone(),
                pair_value_fills: args.pair_value_fills.clone(),
                pairs_shape: args.pairs_shape.clone(),
                variadic: args.variadic.clone(),
                minimum: args.minimum.clone(),
                coerce: args.coerce.clone(),
                blank_message: args.blank_message.clone(),
                status: "admitted".to_string(),
            });
            Ok(())
        },
        &[],
        &syntax_invariants(),
        &["ArgumentAdmitted"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

